CREATE OR REPLACE TRIGGER trg_vente_stock
BEFORE INSERT ON vente
FOR EACH ROW
DECLARE
  v_stock medicament.stock%TYPE;
  v_prix  medicament.prix%TYPE;
BEGIN
  SELECT stock, prix INTO v_stock, v_prix FROM medicament WHERE id_med = :NEW.id_med;

  IF v_stock < :NEW.quantite THEN
    RAISE_APPLICATION_ERROR(-20501, 'Stock insuffisant');
  END IF;

  :NEW.montant := :NEW.quantite * v_prix;          -- BEFORE ligne : on peut modifier :NEW
  UPDATE medicament SET stock = stock - :NEW.quantite WHERE id_med = :NEW.id_med;
END;
/
- Seul un trigger BEFORE par ligne peut modifier :NEW (ici le montant).
- Lecture et mise à jour de MEDICAMENT : table différente de VENTE, donc pas de mutation.

CREATE OR REPLACE FUNCTION chiffreaffairesmois (p_annee IN NUMBER, p_mois IN NUMBER) RETURN NUMBER IS
  v_ca NUMBER;
BEGIN
  SELECT NVL(SUM(montant), 0) INTO v_ca
  FROM vente
  WHERE EXTRACT(YEAR FROM date_vente) = p_annee
    AND EXTRACT(MONTH FROM date_vente) = p_mois;
  RETURN v_ca;
END;
/

CREATE OR REPLACE PROCEDURE reapprovisionner (p_id_med IN NUMBER, p_qte IN NUMBER) IS
BEGIN
  IF p_qte IS NULL OR p_qte <= 0 THEN
    RAISE_APPLICATION_ERROR(-20503, 'Quantite invalide');
  END IF;

  UPDATE medicament SET stock = stock + p_qte WHERE id_med = p_id_med;
  IF SQL%ROWCOUNT = 0 THEN
    RAISE_APPLICATION_ERROR(-20502, 'Medicament inexistant');
  END IF;
END reapprovisionner;
/
- On valide d'abord le paramètre, puis on teste SQL%ROWCOUNT après l'UPDATE.
